//! Rust side of the `tools/verify-miscdeg.ps1` harness.
//!
//! Modes:
//!
//! * `miscdeg doubles <javaFile> <rustFile>`: reads the `<bits> <expected>`
//!   corpus generated by `java-src/MiscDegGen doubles` and writes the same
//!   lines using the port's `Double.toString` / `Float.toString`
//!   ([`jackcess::export::java_double_to_string`] /
//!   [`jackcess::export::java_float_to_string`]);
//! * `miscdeg binary <outDir>`: imports text into an existing table with
//!   `BINARY` and `OLE` columns (the text is stored as the Java serialized
//!   string, like `ColumnImpl.toByteArray`) and dumps the stored bytes;
//! * `miscdeg formats <outDir>`: formats number/date/text/boolean values with
//!   [`jackcess::columnfmt::ColumnFormatter`] and the column `Format`
//!   properties and dumps every result;
//! * `miscdeg bigbin <outDir>`: imports text into a `BIG_BINARY` column (the
//!   value is parsed as a number, like `ColumnImpl.writeFixedLengthField`) and
//!   dumps the stored bytes, including Java's `NumberFormatException` cases;
//! * `miscdeg fmtprops <outDir>`: `ColumnFormatter::set_format_string` (the
//!   `Format` property is saved internally) and the resulting property blobs,
//!   including the error cases.
//!
//! The Java expectations are produced by `java-src/MiscDegGen`, which writes
//! the same files with the same names (`miscdeg_java_*`).

use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};

use jackcess::column::ColumnSpec;
use jackcess::columnfmt::ColumnFormatter;
use jackcess::database::Database;
use jackcess::datatype::DataType;
use jackcess::datenums::LocalDateTime;
use jackcess::error::{Error, Result};
use jackcess::export::{import_text, java_double_to_string, java_float_to_string, ImportOptions};
use jackcess::format::FileFormat;
use jackcess::property::{Property, PropertyMaps, FORMAT_PROP};
use jackcess::tablecreator::TableSpec;
use jackcess::value::Value;

fn main() {
    if let Err(error) = run() {
        eprintln!("miscdeg: {error}");
        std::process::exit(1);
    }
}

fn run() -> Result<()> {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 3 {
        eprintln!("usage: miscdeg <doubles|binary|formats|bigbin|fmtprops> <outDir>");
        std::process::exit(2);
    }
    match args[1].as_str() {
        "doubles" => {
            if args.len() < 4 {
                eprintln!("usage: miscdeg doubles <javaFile> <rustFile>");
                std::process::exit(2);
            }
            doubles(Path::new(&args[2]), Path::new(&args[3]))
        }
        "binary" => binary(Path::new(&args[2])),
        "formats" => formats(Path::new(&args[2])),
        "bigbin" => bigbin(Path::new(&args[2])),
        "fmtprops" => fmtprops(Path::new(&args[2])),
        other => {
            eprintln!("unknown mode {other}");
            std::process::exit(2);
        }
    }
}

// ---------------------------------------------------------------------------
// 1. Double.toString / Float.toString
// ---------------------------------------------------------------------------

fn doubles(java_file: &Path, rust_file: &Path) -> Result<()> {
    let text = fs::read_to_string(java_file)?;
    let mut out = String::with_capacity(text.len());
    for line in text.lines() {
        let mut parts = line.splitn(3, ' ');
        let kind = parts.next().unwrap_or("");
        let bits = parts.next().unwrap_or("");
        let written = match kind {
            "D" => {
                let raw = u64::from_str_radix(bits, 16).unwrap_or(0);
                format!("D {bits} {}\n", java_double_to_string(f64::from_bits(raw)))
            }
            "F" => {
                let raw = u32::from_str_radix(bits, 16).unwrap_or(0);
                format!("F {bits} {}\n", java_float_to_string(f32::from_bits(raw)))
            }
            _ => continue,
        };
        out.push_str(&written);
    }
    fs::write(rust_file, out)?;
    Ok(())
}

// ---------------------------------------------------------------------------
// 2. importing text into BINARY / OLE columns
// ---------------------------------------------------------------------------

fn hex(bytes: &[u8]) -> String {
    let mut out = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        out.push_str(&format!("{byte:02X}"));
    }
    out
}

fn repeat(text: &str, count: usize) -> String {
    let mut out = String::with_capacity(text.len() * count);
    for _ in 0..count {
        out.push_str(text);
    }
    out
}

/// Quotes one field the way the fixture writer does (every field is quoted,
/// embedded quotes are doubled).
fn quote(value: &str) -> String {
    let mut out = String::with_capacity(value.len() + 2);
    out.push('"');
    for c in value.chars() {
        if c == '"' {
            out.push('"');
        }
        out.push(c);
    }
    out.push('"');
    out
}

fn binary(out_dir: &Path) -> Result<()> {
    let db_path = out_dir.join("miscdeg_rust_binary.mdb");
    let _ = fs::remove_file(&db_path);
    let mut db = Database::create(FileFormat::V2003, &db_path)?;
    db.create_table(&TableSpec::new(
        "Bin",
        vec![
            ColumnSpec::new("ID", DataType::Long),
            ColumnSpec::new("Raw", DataType::Binary).with_length(64),
            ColumnSpec::new("Ole", DataType::Ole),
        ],
    ))?;

    let long300 = repeat("0123456789", 30);
    let long70000 = repeat("a", 70_000);
    let rows: Vec<(i32, &str, &str)> = vec![
        (10, "hello", "hello"),
        (11, "", ""),
        (12, "a\u{0}b", "a\u{0}b"),
        (13, "\u{e9}", "\u{e9}"),
        (14, "\u{1F600}", "\u{1F600}"),
        (16, "x", long300.as_str()),
        (17, "y", long70000.as_str()),
        (18, "comma,quote\"here", "comma,quote\"here"),
    ];
    let mut fixture = String::new();
    for (id, raw, ole) in &rows {
        fixture.push_str(&format!("{id},{},{}\n", quote(raw), quote(ole)));
    }

    let mut out = String::new();
    let options = ImportOptions::new("Bin")
        .with_use_existing_table(true)
        .with_header(false);
    let imported = import_text(&fixture, &mut db, &options)?;
    out.push_str(&format!("import={}\n", imported.unwrap_or_default()));

    let mut count = 0usize;
    for (_id, row) in db.read_rows_with_ids("Bin")? {
        let row = row.unwrap_or_default();
        let row_id = row.first().and_then(|v| v.as_i64()).unwrap_or_default();
        let raw = bytes_of(row.get(1));
        let ole = bytes_of(row.get(2));
        count += 1;
        out.push_str(&format!(
            "row {row_id} raw={} ole={}\n",
            hex(&raw),
            hex(&ole)
        ));
    }
    out.push_str(&format!("rows={count}\n"));

    // a java serialized text which does not fit into the row at all
    db.create_table(&TableSpec::new(
        "BinTooLarge",
        vec![
            ColumnSpec::new("ID", DataType::Long),
            ColumnSpec::new("Raw", DataType::Binary).with_length(8),
        ],
    ))?;
    let oversized = format!("1,{}\n", quote(&repeat("z", 8000)));
    let too_large = ImportOptions::new("BinTooLarge")
        .with_use_existing_table(true)
        .with_header(false);
    match import_text(&oversized, &mut db, &too_large) {
        Ok(_) => out.push_str("too-large=ok\n"),
        Err(_) => out.push_str("too-large=failed\n"),
    }
    let too_large_rows = db
        .read_rows_with_ids("BinTooLarge")?
        .into_iter()
        .filter(|(_, row)| row.is_some())
        .count();
    out.push_str(&format!("too-large-rows={too_large_rows}\n"));

    fs::write(out_dir.join("miscdeg_rust_binary.txt"), out)?;
    Ok(())
}

fn bytes_of(value: Option<&Value>) -> Vec<u8> {
    match value {
        Some(Value::Bytes(bytes)) => bytes.clone(),
        _ => Vec::new(),
    }
}

// ---------------------------------------------------------------------------
// 3. ColumnFormatter
// ---------------------------------------------------------------------------

fn esc(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    for c in text.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            other => out.push(other),
        }
    }
    out
}

/// The `THROW:<simple class name>` token the Java generator prints for a
/// runtime exception, derived from the port's error message (the port annotates
/// the Java exceptions it cannot represent).
fn throw_result(error: &jackcess::error::Error) -> String {
    let text = error.to_string();
    if text.contains("ClassCastException") {
        "THROW:ClassCastException".to_string()
    } else if text.contains("NumberFormatException") {
        "THROW:NumberFormatException".to_string()
    } else {
        "THROW:unsupported".to_string()
    }
}

fn dt(y: i32, mo: u32, d: u32, h: u32, mi: u32, s: u32, nano: u32) -> Value {
    Value::DateTime(LocalDateTime::new(y, mo, d, h, mi, s, nano))
}

