fn formats_for(column: &str) -> Vec<&'static str> {
    match column {
        "ID" => vec!["0", "#,##0"],
        "Qty" => vec![
            "0",
            "#,##0",
            "000000",
            "Standard",
            "Percent",
            "Scientific",
            "Fixed",
            "General Number",
            "0.00",
            "$#,##0.00",
            "0;-0;\"zero\"",
            "0.0E+00",
            ">",
            "Yes/No",
        ],
        "Price" => vec![
            "Currency",
            "Euro",
            "#,##0.00",
            "0.0000",
            "Percent",
            "Scientific",
            "Standard",
            "$#,##0.00;($#,##0.00)",
            "Fixed",
        ],
        "Ratio" => vec![
            "0.0000",
            "General Number",
            "Scientific",
            "0.00E+00",
            "#,##0.0#",
            "Percent",
            "Fixed",
            "0",
            "0.0000000000000000",
        ],
        "Score" => vec!["Scientific", "0.000", "General Number", "Fixed"],
        "Small" => vec!["0", "000", "Percent"],
        "Label" => vec!["@", ">", "<", "@@@@@", "&", "\\@lit", "\"pre\"@", "!@", "0"],
        "Note" => vec!["@", ">", "0"],
        "Flag" => vec!["Yes/No", "True/False", "On/Off", "0", "Yes/No;\"?\"", "@"],
        "Stamp" => vec![
            "Short Date",
            "Medium Date",
            "Long Date",
            "General Date",
            "Short Time",
            "Medium Time",
            "Long Time",
            "yyyy-mm-dd",
            "dddd, mmmm d, yyyy",
            "hh:nn:ss AM/PM",
            "m/d/yyyy",
            "yyyy-mm-dd hh:nn:ss",
            "q",
            "ww",
            "ddd",
            "yyyy-mm-dd hh:nn:ss.000",
        ],
        _ => Vec::new(),
    }
}

fn formats(out_dir: &Path) -> Result<()> {
    let db_path: PathBuf = out_dir.join("miscdeg_rust_formats.mdb");
    let _ = fs::remove_file(&db_path);
    let mut db = Database::create(FileFormat::V2003, &db_path)?;
    db.create_table(&TableSpec::new(
        "Fmt",
        vec![
            ColumnSpec::new("ID", DataType::Long),
            ColumnSpec::new("Qty", DataType::Long),
            ColumnSpec::new("Price", DataType::Money),
            ColumnSpec::new("Ratio", DataType::Double),
            ColumnSpec::new("Score", DataType::Float),
            ColumnSpec::new("Small", DataType::Byte),
            ColumnSpec::new("Label", DataType::Text).with_length(40),
            ColumnSpec::new("Note", DataType::Memo),
            ColumnSpec::new("Flag", DataType::Boolean),
            ColumnSpec::new("Stamp", DataType::ShortDateTime),
        ],
    ))?;

    let stored: Vec<(&str, Value)> = vec![
        ("ID", Value::Long(7)),
        ("Qty", Value::Long(42)),
        (
            "Price",
            Value::Decimal {
                unscaled: 1234,
                scale: 2,
            },
        ),
        ("Ratio", Value::Double(1.25)),
        ("Score", Value::Float(2.5)),
        ("Small", Value::Byte(3)),
        ("Label", Value::Text("Row Label".to_string())),
        ("Note", Value::Text("row memo".to_string())),
        ("Flag", Value::Bool(true)),
        ("Stamp", dt(2021, 4, 5, 6, 7, 8, 0)),
    ];
    let row: Vec<Value> = stored.iter().map(|(_, value)| value.clone()).collect();
    db.add_rows("Fmt", std::slice::from_ref(&row))?;
    let row_map: HashMap<String, Value> = stored
        .iter()
        .map(|(name, value)| (name.to_string(), value.clone()))
        .collect();

    let columns = [
        "ID", "Qty", "Price", "Ratio", "Score", "Small", "Label", "Note", "Flag", "Stamp",
    ];
    let mut out = String::new();
    for column_name in columns {
        let mut format_list: Vec<Option<&str>> =
            formats_for(column_name).into_iter().map(Some).collect();
        format_list.push(None); // no Format property
        format_list.push(Some("")); // empty Format property
        for format in format_list {
            let mut maps = db.get_table_properties_by_name("Fmt")?;
            {
                let map = maps.get_mut(column_name);
                match format {
                    Some(text) if !text.is_empty() => {
                        map.put(Property::new(
                            FORMAT_PROP.to_string(),
                            DataType::Text,
                            Value::Text(text.to_string()),
                        ));
                    }
                    _ => {
                        map.remove(FORMAT_PROP);
                    }
                }
            }
            db.save_properties(&mut maps)?;
            let column = db
                .get_table("Fmt")?
                .get_column(column_name)
                .expect("the test column exists")
                .clone();
            let format_label = match format {
                None => "<none>".to_string(),
                Some(text) => text.to_string(),
            };
            let formatter = match ColumnFormatter::new(&column, &maps) {
                Ok(formatter) => formatter,
                Err(_) => {
                    out.push_str(&format!(
                        "{column_name}\t{}\tINVALID\tINVALID\n",
                        esc(&format_label)
                    ));
                    continue;
                }
            };
            for (label, value) in values(column_name) {
                let text = match formatter.try_format(&value) {
                    Ok(text) => text,
                    Err(error) => throw_result(&error),
                };
                out.push_str(&format!(
                    "{column_name}\t{}\t{label}\t{}\n",
                    esc(&format_label),
                    esc(&text)
                ));
            }
            let map_text = match formatter.try_get_row_value_named(row_map.iter()) {
                Ok(text) => text,
                Err(error) => throw_result(&error),
            };
            out.push_str(&format!(
                "{column_name}\t{}\t<map>\t{}\n",
                esc(&format_label),
                esc(&map_text)
            ));
            let array_text = match formatter.try_get_row_value(&row) {
                Ok(text) => text,
                Err(error) => throw_result(&error),
            };
            out.push_str(&format!(
                "{column_name}\t{}\t<row>\t{}\n",
                esc(&format_label),
                esc(&array_text)
            ));
        }
    }

    // an invalid pattern fails when the formatter is built
    let mut maps = db.get_table_properties_by_name("Fmt")?;
    maps.get_mut("Label").put(Property::new(
        FORMAT_PROP.to_string(),
        DataType::Text,
        Value::Text("\"unterminated".to_string()),
    ));
    db.save_properties(&mut maps)?;
    let column = db
        .get_table("Fmt")?
        .get_column("Label")
        .expect("the Label column exists")
        .clone();
    match ColumnFormatter::new(&column, &maps) {
        Ok(_) => out.push_str("invalid-format=accepted\n"),
        Err(_) => out.push_str("invalid-format=rejected\n"),
    }

    fs::write(out_dir.join("miscdeg_rust_formats.txt"), out)?;
    Ok(())
}

// ---------------------------------------------------------------------------
// 4. BIG_BINARY text import: the value is parsed as a number
// ---------------------------------------------------------------------------

fn bigbin(out_dir: &Path) -> Result<()> {
    // the database *name* is part of Java's BatchUpdateException message, so
    // both halves use the same file name in their own directory
    let dir = out_dir.join("rust");
    fs::create_dir_all(&dir)?;
    let db_path = dir.join("miscdeg_bigbin.mdb");
    let _ = fs::remove_file(&db_path);
    let mut db = Database::create(FileFormat::V2003, &db_path)?;
    db.create_table(&TableSpec::new(
        "Bin",
        vec![
            ColumnSpec::new("ID", DataType::Long),
            ColumnSpec::new("Ref", DataType::BigBinary),
        ],
    ))?;

    // `writeFixedLengthField` -> `toNumber(text).intValue()`
    let values = [
        "12",
        "-7",
        "3.9",
        "1e3",
        " 42 ",
        "NaN",
        "Infinity",
        "2147483648",
        "-2147483649",
        "0x1p3",
        "0x1.8p1",
        "0x1p3f",
        "1d",
        "2.5f",
        "  -0.9  ",
    ];
    let mut fixture = String::new();
    for (i, value) in values.iter().enumerate() {
        fixture.push_str(&format!("{},{}\n", i + 1, quote(value)));
    }
    let options = ImportOptions::new("Bin")
        .with_use_existing_table(true)
        .with_header(false);
    import_text(&fixture, &mut db, &options)?;

    let mut out = String::new();
    for (_id, row) in db.read_rows_with_ids("Bin")? {
        let row = row.unwrap_or_default();
        let id = row
            .first()
            .and_then(|value| value.as_i64())
            .unwrap_or_default();
        out.push_str(&format!("bigbin {id} {}\n", hex(&bytes_of(row.get(1)))));
    }

    // text which is not a number: Java's NumberFormatException inside the
    // batch exception, and no row written
    for bad in ["abc", "", "1x", "inf"] {
        let line = format!("1,{}\n", quote(bad));
        match import_text(&line, &mut db, &options) {
            Ok(_) => out.push_str(&format!("error [{}] none\n", esc(bad))),
            Err(error) => out.push_str(&format!(
                "error [{}] {}\n",
                esc(bad),
                error.java_to_string()
            )),
        }
    }
    let count = db
        .read_rows_with_ids("Bin")?
        .into_iter()
        .filter(|(_, row)| row.is_some())
        .count();
    out.push_str(&format!("rows={count}\n"));

    fs::write(out_dir.join("miscdeg_rust_bigbin.txt"), out)?;
    Ok(())
}

// ---------------------------------------------------------------------------
// 5. ColumnFormatter.setFormatString saves the Format property
// ---------------------------------------------------------------------------

fn fmt_of(formatter: &ColumnFormatter) -> String {
    match formatter.get_format_string() {
        Some(fmt) => fmt.to_string(),
        None => "<none>".to_string(),
    }
}

/// The `Format` property of the `Qty` column (`Column.getProperties()
/// .getValue`)
fn prop_of(maps: &PropertyMaps) -> String {
    match maps.get("Qty").and_then(|map| map.get_value(FORMAT_PROP)) {
        Some(Value::Text(text)) => text.clone(),
        Some(other) => format!("{other:?}"),
        None => "<none>".to_string(),
    }
}

/// The simple name of the Java exception class the error corresponds to.
fn java_class(error: &Error) -> &'static str {
    match error {
        Error::Io(io) if io.to_string().contains("NonWritableChannelException") => {
            "java.nio.channels.NonWritableChannelException"
        }
        Error::Io(_) | Error::Jackcess(_) => "java.io.IOException",
        Error::IllegalArgument(_) => "java.lang.IllegalArgumentException",
        Error::IllegalState(_) => "java.lang.IllegalStateException",
        Error::InvalidCredentials(_) => {
            "com.healthmarketscience.jackcess.crypt.InvalidCredentialsException"
        }
        Error::Unsupported(_) => "java.lang.UnsupportedOperationException",
        Error::ConstraintViolation(_) => {
            "com.healthmarketscience.jackcess.ConstraintViolationException"
        }
        Error::InvalidValue(_) => "com.healthmarketscience.jackcess.InvalidValueException",
        Error::BatchUpdate { .. } => "com.healthmarketscience.jackcess.BatchUpdateException",
        Error::BufferUnderflow(_) => "java.nio.BufferUnderflowException",
        Error::BufferOverflow(_) => "java.nio.BufferOverflowException",
        Error::InvalidMark => "java.nio.InvalidMarkException",
        Error::NumberFormat(_) => "java.lang.NumberFormatException",
    }
}

/// Java's `Throwable.getMessage()` (`null` is printed as `null`).
fn java_message(error: &Error) -> String {
    match error {
        Error::Io(io) if io.to_string().contains("NonWritableChannelException") => {
            "null".to_string()
        }
        Error::Io(io) => io.to_string(),
        Error::Jackcess(message)
        | Error::IllegalArgument(message)
        | Error::IllegalState(message)
        | Error::InvalidCredentials(message)
        | Error::Unsupported(message)
        | Error::ConstraintViolation(message)
        | Error::InvalidValue(message)
        | Error::BufferUnderflow(message)
        | Error::BufferOverflow(message)
        | Error::NumberFormat(message) => message.clone(),
        Error::BatchUpdate { message, .. } => message.clone(),
        Error::InvalidMark => "null".to_string(),
    }
}

/// The raw `LvProp` blob of the catalog row of the given table
/// (`ErrorHandlerGen`-style: read it back from `MSysObjects`).
fn lvprop_hex(db: &mut Database, table_name: &str) -> Result<String> {
    let columns = db.get_table("MSysObjects")?.columns.clone();
    let name_index = columns
        .iter()
        .position(|c| c.name.eq_ignore_ascii_case("Name"));
    let lv_index = columns
        .iter()
        .position(|c| c.name.eq_ignore_ascii_case("LvProp"));
    let (name_index, lv_index) = match (name_index, lv_index) {
        (Some(name), Some(lv)) => (name, lv),
        _ => return Ok("absent".to_string()),
    };
    for (_id, row) in db.read_rows_with_ids("MSysObjects")? {
        let row = match row {
            Some(row) => row,
            None => continue,
        };
        let name = match row.get(name_index) {
            Some(Value::Text(name)) => name,
            _ => continue,
        };
        if name.eq_ignore_ascii_case(table_name) {
            return Ok(match row.get(lv_index) {
                Some(Value::Bytes(bytes)) => hex(bytes),
                _ => "null".to_string(),
            });
        }
    }
    Ok("absent".to_string())
}

fn fmtprops(out_dir: &Path) -> Result<()> {
    // both halves use the same database name (see `bigbin`)
    let dir = out_dir.join("rust");
    fs::create_dir_all(&dir)?;
    let db_path = dir.join("miscdeg_fmtprops.mdb");
    let _ = fs::remove_file(&db_path);

    let mut out = String::new();
    {
        let mut db = Database::create(FileFormat::V2003, &db_path)?;
        db.create_table(&TableSpec::new(
            "Fmt",
            vec![
                ColumnSpec::new("ID", DataType::Long),
                ColumnSpec::new("Qty", DataType::Long),
                ColumnSpec::new("Label", DataType::Text).with_length(40),
            ],
        ))?;
        db.add_rows(
            "Fmt",
            &[vec![
                Value::Long(1),
                Value::Long(1_234_567),
                Value::Text("x".to_string()),
            ]],
        )?;
        let qty = db.get_table("Fmt")?.get_column("Qty").unwrap().clone();
        let mut maps = db.get_table_properties_by_name("Fmt")?;
        let mut formatter = ColumnFormatter::new(&qty, &maps)?;
        out.push_str(&format!(
            "initial fmt={} prop={}\n",
            fmt_of(&formatter),
            prop_of(&maps)
        ));
        formatter.set_format_string(&mut db, &mut maps, Some("#,##0"))?;
        out.push_str(&format!(
            "set fmt={} prop={} out={}\n",
            fmt_of(&formatter),
            prop_of(&maps),
            formatter.format(&Value::Long(1_234_567))
        ));
        out.push_str(&format!("blob={}\n", lvprop_hex(&mut db, "Fmt")?));
        formatter.set_format_string(&mut db, &mut maps, None)?;
        out.push_str(&format!(
            "remove fmt={} prop={}\n",
            fmt_of(&formatter),
            prop_of(&maps)
        ));
        formatter.set_format_string(&mut db, &mut maps, Some("$#,##0.00"))?;
        out.push_str(&format!(
            "set2 fmt={} out={}\n",
            fmt_of(&formatter),
            formatter.format(&Value::Long(1_234_567))
        ));
        out.push_str(&format!("blob2={}\n", lvprop_hex(&mut db, "Fmt")?));
    }

    // the saved property is on disk: a fresh handle reads it back
    {
        let mut db = Database::open_path_read_only(&db_path)?;
        let qty = db.get_table("Fmt")?.get_column("Qty").unwrap().clone();
        let maps = db.get_table_properties_by_name("Fmt")?;
        let formatter = ColumnFormatter::new(&qty, &maps)?;
        out.push_str(&format!(
            "reopen prop={} fmt={}\n",
            prop_of(&maps),
            fmt_of(&formatter)
        ));
        out.push_str(&format!("reopen blob={}\n", lvprop_hex(&mut db, "Fmt")?));
    }

    // read-only: the property map is updated, the save fails with
    // `NonWritableChannelException`, and the formatter is not reloaded
    {
        let mut db = Database::open_path_read_only(&db_path)?;
        let qty = db.get_table("Fmt")?.get_column("Qty").unwrap().clone();
        let mut maps = db.get_table_properties_by_name("Fmt")?;
        let mut formatter = ColumnFormatter::new(&qty, &maps)?;
        match formatter.set_format_string(&mut db, &mut maps, Some("0.00")) {
            Ok(()) => out.push_str("readonly raised=no\n"),
            Err(error) => out.push_str(&format!(
                "readonly class={} message={}\n",
                java_class(&error),
                java_message(&error)
            )),
        }
        out.push_str(&format!(
            "readonly fmt={} prop={}\n",
            fmt_of(&formatter),
            prop_of(&maps)
        ));
    }
    {
        let mut db = Database::open_path_read_only(&db_path)?;
        let maps = db.get_table_properties_by_name("Fmt")?;
        out.push_str(&format!("after-readonly prop={}\n", prop_of(&maps)));
    }

    // an invalid pattern: the property is saved, then the reload fails
    // (the port has no ParseException error kind and its parser message
    // differs, so only the raise and the saved state are compared)
    {
        let mut db = Database::open_path(&db_path)?;
        let qty = db.get_table("Fmt")?.get_column("Qty").unwrap().clone();
        let mut maps = db.get_table_properties_by_name("Fmt")?;
        let mut formatter = ColumnFormatter::new(&qty, &maps)?;
        match formatter.set_format_string(&mut db, &mut maps, Some("\"unterminated")) {
            Ok(()) => out.push_str("invalid raised=no\n"),
            Err(_) => out.push_str("invalid raised=yes\n"),
        }
        out.push_str(&format!(
            "invalid fmt={} prop={} blob={}\n",
            fmt_of(&formatter),
            prop_of(&maps),
            lvprop_hex(&mut db, "Fmt")?
        ));
    }
    {
        let mut db = Database::open_path_read_only(&db_path)?;
        let maps = db.get_table_properties_by_name("Fmt")?;
        out.push_str(&format!("after-invalid prop={}\n", prop_of(&maps)));
        out.push_str(&format!(
            "after-invalid blob={}\n",
            lvprop_hex(&mut db, "Fmt")?
        ));
    }

    fs::write(out_dir.join("miscdeg_rust_fmtprops.txt"), out)?;
    Ok(())
}
